"""ATHBA initial production module."""


class RunningTotal:
    """A container that exposes calculated totals."""

    def __init__(self):
        self._total = 0

    def add(self, value):
        """Add a value to the running total."""
        self._total += value

    @property
    def total(self):
        """Get the current running total."""
        return self._total

    def get(self):
        """Get the current running total."""
        return self._total
